function showBeasts(){let dead=normalizeDefeats(JSON.parse(window.abyssStorageGet('abyssDefeated')||'{}')),grid=$('#collectionGrid'),g=window.getAbyssGame?.(),abyssOpen=window.abyssStorageGet('abyssRegionUnlocked')==='1'||g?.act===4||g?.secretMap||g?.secretCleared||dead['深淵の監視者・フグ店長']||dead['深淵の守護者・クトゥル＝アビス'],deepNames=new Set(['深淵の監視者・フグ店長','深淵の守護者・クトゥル＝アビス','虚星邪神・クトゥル＝アビス']),card=b=>{if(deepNames.has(b.n)&&!abyssOpen)return '<article class="beast-card locked abyss-sealed"><div class="beast-img"><span>？</span></div><h3>？？？？？</h3><p class="beast-location">📍 ？？？？？</p><p>？？？？？？？？？？</p></article>';let seen=dead[b.n];return `<article class="beast-card ${seen?'seen':'locked'}"${seen?` data-beast="${b.n}" role="button" tabindex="0"`:''}><div class="beast-img direct-enemy ${b.gen?'generated-enemy':''}" style="--bestiary-facing:${BESTIARY_FLIP.has(b.file)?-1:1};background-image:url('assets/enemies/${b.file}?v=101')"></div><h3>${seen?b.n:'？？？？？'}</h3><p class="beast-location">📍 ${beastPlace(b.n)}</p><p>${seen?b.desc:'たおすと特徴がわかります。'}</p>${seen?`<p class="beast-count">討伐 ${dead[b.n]}回 <span class="beast-more">行動パターンを見る ›</span></p>`:''}</article>`};grid.className='modal-shell-body collection-grid beast-legacy-grid';$('#collectionTitle').textContent='深海生物図鑑';$('#collectionSub').textContent=`見つけた生き物 ${BEASTS.filter(b=>dead[b.n]).length} / ${BEASTS.length}`;grid.innerHTML=BEAST_GROUPS.map(([title,subtitle,names])=>`<header class="beast-layer-heading"><span>${title}</span><small>${subtitle}</small></header>${names.map(name=>BEASTS.find(b=>b.n===name)).filter(Boolean).map(card).join('')}`).join('');grid.querySelectorAll('.beast-card[data-beast]').forEach(el=>{let open=()=>showBeastDetail(el.dataset.beast);el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});$('#collectionModal').classList.add('on');window.applyFuri?.($('#collectionModal'))}
window.openAbyssBestiary=showBeasts;
function moveIcon(m){let hits=m.h||1,canFeed=m.feed&&m.a,parts=[];if(m.a)parts.push(`<span class="move-tag atk">⚔ 攻撃 ${hits>1?`${m.a}×${hits}（計${m.a*hits}）`:m.a}</span>`);if(m.b)parts.push(`<span class="move-tag def">🛡 防御 ${m.b}</span>`);if(m.p)parts.push(`<span class="move-tag poison">☠ 毒針 ＋${m.p}</span>`);
if(m.weakenPlayer)parts.push('<span class="move-tag gimmick">💧 脱力：次のターンの与ダメージ−25%</span>');if(m.burrow)parts.push('<span class="move-tag gimmick">🕳 潜行：次のターンの被ダメージ半減</span>');if(m.stunThreshold)parts.push(`<span class="move-tag gimmick">💫 気絶条件：このターンに${m.stunThreshold}ダメージ</span>`);if(m.pressure)parts.push(`<span class="move-tag gimmick">🌊 潮圧：次のエナジー−${m.pressure}</span>`);if(m.handCostUp)parts.push(`<span class="move-tag gimmick">💰 妨害：次のターンの手札コスト＋${m.handCostUp}</span>`);if(m.thornsSelf)parts.push(`<span class="move-tag gimmick">🦔 トゲを纏う：次のターン＋${m.thornsSelf}</span>`);if(canFeed)parts.push(`<span class="move-tag gimmick">🩸 捕食：1命中ごとにHP＋${m.feed}</span>`);if(m.devour)parts.push(`<span class="move-tag gimmick">🫧 毒喰い：毒を消し防御＋${m.devour}</span>`);
if(m.counter)parts.push(`<span class="move-tag gimmick">👁 反応：4枚目から攻撃全体＋${m.counter}</span>`);
if(m.buff)parts.push(`<span class="move-tag gimmick">🔥 深海増幅：攻撃＋${m.buff}</span>`);if(m.giveCurse)parts.push(`<span class="move-tag gimmick">🜏 呪い混入：捨て札に呪いカードを追加</span>`);if(m.curseDraw)parts.push(`<span class="move-tag gimmick">🜏 呪い混入：山札に呪いカードを追加</span>`);if(m.stealBlock)parts.push(`<span class="move-tag gimmick">🦶 強奪：ブロックを${m.stealBlock}奪う</span>`);if(m.denyDraw)parts.push(`<span class="move-tag gimmick">🌑 妨害：次のターンの手札−${m.denyDraw}</span>`);if(m.randomizeTop)parts.push(`<span class="move-tag gimmick">🌀 攪乱：山札の一番上のコストを乱す</span>`);if(m.discardExhaust)parts.push(`<span class="move-tag gimmick">🕳 侵食：捨て札から1枚を除外</span>`);return parts.join('')||'<span class="move-tag">－</span>'}
function ensureBeastDetailModal(){if($('#beastDetailModal'))return;let m=document.createElement('div');m.className='modal';m.id='beastDetailModal';m.innerHTML=`<div class="panel beast-detail-panel modal-shell"><header class="modal-shell-head beast-detail-head"><div class="beast-detail-portrait direct-enemy" id="beastDetailPortrait"></div><div class="beast-detail-heading"><small>DEEP SEA CODEX</small><h2 id="beastDetailName"></h2><p class="beast-location" id="beastDetailPlace"></p></div></header><div class="modal-shell-body beast-detail-body"><p class="beast-detail-desc" id="beastDetailDesc"></p><p class="beast-detail-trait" id="beastDetailTrait" hidden></p><h3 class="beast-pattern-heading">⚔ 行動パターン</h3><ol class="beast-pattern-list" id="beastDetailMoves"></ol><p class="beast-detail-count" id="beastDetailCount"></p></div><footer class="modal-shell-foot"><button class="btn" id="beastDetailClose">閉じる</button></footer></div>`;document.body.appendChild(m);$('#beastDetailClose').onclick=()=>m.classList.remove('on');m.onclick=e=>{if(e.target===m)m.classList.remove('on')}}
function showBeastDetail(name){let b=BEASTS.find(x=>x.n===name);if(!b)return;ensureBeastDetailModal();let dead=normalizeDefeats(JSON.parse(window.abyssStorageGet('abyssDefeated')||'{}')),count=dead[b.n]||0,portrait=$('#beastDetailPortrait');portrait.className=`beast-detail-portrait direct-enemy ${b.gen?'generated-enemy':''}`;portrait.style.setProperty('--bestiary-facing',BESTIARY_FLIP.has(b.file)?-1:1);portrait.style.backgroundImage=`url('assets/enemies/${b.file}?v=101')`;$('#beastDetailName').textContent=b.n;$('#beastDetailPlace').textContent=`📍 ${beastPlace(b.n)}`;$('#beastDetailDesc').textContent=b.desc;let entry=window.getAbyssEnemyPattern?.(b.n),traitEl=$('#beastDetailTrait');if(entry?.trait){traitEl.hidden=false;traitEl.innerHTML=`<b>特性</b> ${entry.trait}`}else traitEl.hidden=true;let moves=entry?.m||[];$('#beastDetailMoves').innerHTML=moves.map((m,i)=>`<li><span class="pattern-index">${i+1}</span><div class="pattern-tags">${moveIcon(m)}</div></li>`).join('')||'<li><span class="pattern-index">?</span><div class="pattern-tags">記録なし</div></li>';$('#beastDetailCount').textContent=count?`討伐 ${count}回`:'';$('#beastDetailModal').classList.add('on');window.applyFuri?.($('#beastDetailModal'))}
inject();
